def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find minimal edit between strings."""
    # Simple approach: find first difference
    for i in range(min(len(s_in), len(s_out))):
        if s_in[i] != s_out[i]:
            return (s_in[i], s_out[i], i)

    # If prefixes match, check length difference
    if len(s_in) < len(s_out):
        return ('', s_out[len(s_in):], len(s_in))
    elif len(s_in) > len(s_out):
        return (s_in[len(s_out):], '', len(s_out))
    return ('', '', -1)

def propose_rule_candidates(s_in, s_out):
    """Propose replacement rules from transformation."""
    candidates = []

    # Character-level replacements
    for i in range(min(len(s_in), len(s_out))):
        if s_in[i] != s_out[i]:
            candidates.append((s_in[i], s_out[i]))

    # Try 2-character patterns
    for i in range(min(len(s_in), len(s_out)) - 1):
        if s_in[i:i+2] != s_out[i:i+2]:
            candidates.append((s_in[i:i+2], s_out[i:i+2]))

    # Try 3-character patterns  
    for i in range(min(len(s_in), len(s_out)) - 2):
        if s_in[i:i+3] != s_out[i:i+3]:
            candidates.append((s_in[i:i+3], s_out[i:i+3]))

    # Remove duplicates and sort by specificity
    seen = set()
    unique = []
    for pat, rep in candidates:
        if (pat, rep) not in seen:
            seen.add((pat, rep))
            unique.append((pat, rep))

    # Sort by pattern length (shorter first)
    unique.sort(key=lambda x: len(x[0]))
    return unique

def apply_rules(strings, rules):
    """Apply rules sequentially."""
    result = strings[:]
    for pattern, replacement in rules:
        result = [s.replace(pattern, replacement) for s in result]
    return result

