outputs = ['azy', 'wyxed', 'igwifeavx', 'vazdcvgwif', 'ii']

print("Finding changed pairs:")
changed = find_changed_pairs(inputs, outputs)
print(changed)

# Analyze the first changed pair
if len(changed) > 0:
    idx1, s_in1, s_out1 = changed[0]
    print(f"\nAnalyzing pair {idx1}: '{s_in1}' -> '{s_out1}'")

    # Find minimal edit
    old_sub, new_sub, pos = find_minimal_edit(s_in1, s_out1)
    print(f"Minimal edit: '{old_sub}' -> '{new_sub}' at position {pos}")

    # Propose candidates
    candidates = propose_rule_candidates(s_in1, s_out1)
    print(f"Candidates: {candidates}")

# Analyze the second changed pair  
if len(changed) > 1:
    idx2, s_in2, s_out2 = changed[1]
    print(f"\nAnalyzing pair {idx2}: '{s_in2}' -> '{s_out2}'")

    # Find minimal edit
    old_sub, new_sub, pos = find_minimal_edit(s_in2, s_out2)
    print(f"Minimal edit: '{old_sub}' -> '{new_sub}' at position {pos}")

    # Propose candidates
    candidates = propose_rule_candidates(s_in2, s_out2)
    print(f"Candidates: {candidates}")

# Now let's try a proper rule-building approach
print("\n=== Trying to build rules ===")

